    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- steps-days-per-week
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('58929ab5-72ec-5a41-941b-be5f29965932', 'steps-days-per-week', '8,000 steps on one or two days a week: what ten years of death records show', '10.1001/jamanetworkopen.2023.5174', 'Movement', 'Among 3,101 US adults, reaching 8,000 steps on only 1 to 2 days a week was associated with a 10-year risk of death 14.9 points lower than never reaching it. The comparison is less clean than it sounds.', 'free', '2026-11-12T00:00:00Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('58929ab5-72ec-5a41-941b-be5f29965932', '{"hook":[{"text":"Step counts are usually sold as a daily target.","refs":[]},{"text":"This study asked a different question: does it matter on how many days of the week you get there?","refs":["threshold"]}],"populationPanel":[{"text":"Who was studied: 3,101 US adults aged 20 or older who wore an accelerometer for 1 week in 2005-2006 and were then traced through national death records.","refs":["sample","cohort"]},{"text":"Nobody was assigned to walk more or less, so this is an observational study.","refs":["cohort"]},{"text":"It describes these adults. It is not a prescription.","refs":[]}],"sections":[{"id":"found","heading":"What they found","paragraphs":[[{"text":"Researchers sorted people by how many days that week they reached 8,000 steps: none, 1 to 2 days, or 3 to 7 days.","refs":["threshold"]},{"text":"Within 10 years, 40.7% of the people with no such days had died, against 14.1% of those with 1 to 2 days and 5.5% of those with 3 to 7.","refs":["followup","threshold","crude_0","crude_1_2","crude_3_7"]}],[{"text":"Those raw figures flatter walking, because the three groups were very different people.","refs":[]},{"text":"After the researchers accounted for age, sex, smoking, existing illness and average daily steps, the 1-to-2-day group still had a 10-year risk of death 14.9 points lower than the zero-day group.","refs":["ard_1_2","followup","models"]},{"text":"For 3 to 7 days the figure was 16.5 points.","refs":["ard_3_7"]},{"text":"That is only a little more, and the curve went flat at 3 to 4 days.","refs":["plateau"]}]]},{"id":"lower-bound","heading":"How sure is that number?","paragraphs":[[{"text":"The 95% confidence interval for the 1-to-2-day group runs from 18.8 points down to 10.9 points.","refs":["ard_1_2"]},{"text":"So even the weakest reading that fits the data is a 10.9-point gap, which is wide for a study of deaths.","refs":["ard_1_2"]},{"text":"What the interval cannot tell you is whether the walking is the reason for the gap.","refs":[]}]]},{"id":"missed","heading":"What most summaries miss","paragraphs":[[{"text":"The zero-day group had a mean age of 63.7.","refs":["ages"]},{"text":"The 3-to-7-day group had a mean age of 46.0.","refs":["ages","threshold"]},{"text":"Half of the zero-day group, 50.5%, said they had difficulty walking 0.25 miles or climbing 10 stairs, against 6.8% of the most active group.","refs":["mobility","mobility_def"]}],[{"text":"People who are already unwell walk less and die sooner, so part of the gap is illness, not walking.","refs":["confounding"]},{"text":"The authors adjusted for this and say plainly that some of it remains.","refs":["confounding"]}],[{"text":"One more detail: the gap was 7.4 points in adults under 65 and 19.9 points in those 65 and over.","refs":["ard_1_2_under65","ard_1_2_65plus"]}]]},{"id":"parallel","heading":"A related idea","paragraphs":[[{"text":"The authors point to an earlier pooled analysis in which risk stopped falling at 6,000 to 8,000 steps a day for adults over 60, and at 8,000 to 10,000 for younger adults.","refs":["parallel_meta"]},{"text":"Both findings describe the same shape from two directions: steep at the bottom, flat at the top.","refs":["parallel_meta","plateau"]}],[{"text":"Moving the daily threshold anywhere between 6,000 and 10,000 steps gave similar results, so 8,000 is a convenient marker, not a magic line.","refs":["thresholds","threshold"]}]]}],"limitations":[[{"text":"Steps were measured for only 1 week, at the start.","refs":["one_week"]},{"text":"How these people walked over the following 10 years is unknown.","refs":["one_week","followup"]}],[{"text":"This is an observational study.","refs":["cohort"]},{"text":"People in poor health walk less and are more likely to die, and no adjustment removes that completely.","refs":["confounding"]}],[{"text":"Wearing a tracker can make people more active for that week, which would place some usually inactive people in the wrong group.","refs":["hawthorne"]}]],"figure":{"figure":"seen-together","caption":[{"text":"The gap in deaths that went with days at 8,000 steps.","refs":["threshold","ard_1_2","ard_3_7"]},{"text":"The study watched people and assigned nothing, so this figure has no arrow.","refs":[]}],"alt":"Two bars and a bracket. For people with 1 to 2 step days a week, the risk of death was 14.9 points lower. For people with 3 to 7 step days, it was 16.5 points lower. The bracket under both bars says they were seen together.","params":{"threshold":{"n":8000,"ref":"threshold"},"years":{"n":10,"ref":"followup"},"few":{"kind":"measured","fact":{"id":"ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days vs 0 days, all-cause","quote":"all-cause mortality risk was lower among those who took 8000 steps or more 1 to 2 days per week (aRD, −14.9%; 95% CI −18.8% to −10.9%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-14.9,"ciLow":-18.8,"ciHigh":-10.9,"unit":"points","absolute":true,"tier":"low"}},"from":{"n":1,"ref":"threshold"},"to":{"n":2,"ref":"threshold"}},"many":{"kind":"measured","fact":{"id":"ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days vs 0 days, all-cause","quote":"3 to 7 days per week (aRD, −16.5%; 95% CI, −20.4% to −12.5%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-16.5,"ciLow":-20.4,"ciHigh":-12.5,"unit":"points","absolute":true,"tier":"low"}},"from":{"n":3,"ref":"threshold"},"to":{"n":7,"ref":"threshold"}}}},"primaryEstimate":"ard_1_2","simulator":{"kind":"steps-days","params":{"threshold":{"n":8000,"ref":"threshold"},"followupYears":{"n":10,"ref":"followup"},"groups":[{"id":"g0","label":"No days","from":{"n":0,"ref":"threshold"},"to":{"n":0,"ref":"threshold"},"meanAge":{"n":63.7,"ref":"ages"}},{"id":"g1","label":"1 to 2 days","from":{"n":1,"ref":"threshold"},"to":{"n":2,"ref":"threshold"},"meanAge":{"n":51.5,"ref":"ages"}},{"id":"g2","label":"3 to 7 days","from":{"n":3,"ref":"threshold"},"to":{"n":7,"ref":"threshold"},"meanAge":{"n":46,"ref":"ages"}}],"outcomes":[{"id":"all","label":"Death from any cause","crude":{"g0":{"id":"crude_0","kind":"estimate","label":"Share of the 0-day group who died within 10 years, unadjusted","quote":"257/632 (40.7)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":40.7,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g1":{"id":"crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died within 10 years, unadjusted","quote":"75/532 (14.1)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":14.1,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g2":{"id":"crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died within 10 years, unadjusted","quote":"107/1937 (5.5)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":5.5,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}}},"models":[{"id":"agesex","label":"Age and sex","g1":{"id":"ard_1_2_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 1-2 days, all-cause","quote":"−18.7 (−23.2 to −14.4)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-18.7,"ciLow":-23.2,"ciHigh":-14.4,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"ard_3_7_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 3-7 days, all-cause","quote":"−23.0 (−26.8 to −19.3)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-23,"ciLow":-26.8,"ciHigh":-19.3,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m1","label":"Plus health and lifestyle","g1":{"id":"ard_1_2_m1","kind":"estimate","label":"Risk difference, model 1 (demographics, health, lifestyle), 1-2 days, all-cause","quote":"−15.9 (−20.0 to −11.8)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-15.9,"ciLow":-20,"ciHigh":-11.8,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"ard_3_7_m1","kind":"estimate","label":"Risk difference, model 1, 3-7 days, all-cause","quote":"−19.4 (−23.0 to −15.8)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-19.4,"ciLow":-23,"ciHigh":-15.8,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m2","label":"Plus average daily steps","g1":{"id":"ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days vs 0 days, all-cause","quote":"all-cause mortality risk was lower among those who took 8000 steps or more 1 to 2 days per week (aRD, −14.9%; 95% CI −18.8% to −10.9%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-14.9,"ciLow":-18.8,"ciHigh":-10.9,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days vs 0 days, all-cause","quote":"3 to 7 days per week (aRD, −16.5%; 95% CI, −20.4% to −12.5%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-16.5,"ciLow":-20.4,"ciHigh":-12.5,"unit":"points","absolute":true,"tier":"low"}}}]},{"id":"cv","label":"Cardiovascular death","crude":{"g0":{"id":"cv_crude_0","kind":"estimate","label":"Share of the 0-day group who died of cardiovascular disease, unadjusted","quote":"87/462 (18.8)","estimate":{"outcome":"Cardiovascular deaths within 10 years, unadjusted","measure":"proportion","point":18.8,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g1":{"id":"cv_crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died of cardiovascular disease, unadjusted","quote":"26/483 (5.4)","estimate":{"outcome":"Cardiovascular deaths within 10 years, unadjusted","measure":"proportion","point":5.4,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"g2":{"id":"cv_crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died of cardiovascular disease, unadjusted","quote":"35/1865 (1.9)","estimate":{"outcome":"Cardiovascular deaths within 10 years, unadjusted","measure":"proportion","point":1.9,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}}},"models":[{"id":"agesex","label":"Age and sex","g1":{"id":"cv_ard_1_2_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 1-2 days, cardiovascular","quote":"−9.6 (−12.9 to −6.3)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-9.6,"ciLow":-12.9,"ciHigh":-6.3,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"cv_ard_3_7_agesex","kind":"estimate","label":"Risk difference adjusted for age and sex only, 3-7 days, cardiovascular","quote":"−11.1 (−14.4 to −7.9)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-11.1,"ciLow":-14.4,"ciHigh":-7.9,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m1","label":"Plus health and lifestyle","g1":{"id":"cv_ard_1_2_m1","kind":"estimate","label":"Risk difference, model 1, 1-2 days, cardiovascular","quote":"−8.5 (−12.2 to −4.9)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.5,"ciLow":-12.2,"ciHigh":-4.9,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"cv_ard_3_7_m1","kind":"estimate","label":"Risk difference, model 1, 3-7 days, cardiovascular","quote":"−9.8 (−13.4 to −6.2)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-9.8,"ciLow":-13.4,"ciHigh":-6.2,"unit":"points","absolute":true,"tier":"low"}}},{"id":"m2","label":"Plus average daily steps","g1":{"id":"cv_ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days, cardiovascular","quote":"(aRD, −8.1%; 95% CI, −11.8% to −4.4%)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.1,"ciLow":-11.8,"ciHigh":-4.4,"unit":"points","absolute":true,"tier":"low"}},"g2":{"id":"cv_ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days, cardiovascular","quote":"(aRD, −8.4%; 95% CI, −12.5% to −4.4%)","estimate":{"outcome":"10-year risk of cardiovascular death","measure":"aRD","point":-8.4,"ciLow":-12.5,"ciHigh":-4.4,"unit":"points","absolute":true,"tier":"low"}}}]}],"modelNote":{"id":"models","kind":"context","label":"What each adjustment model added","quote":"Model 1 included age; sex; race and ethnicity; insurance status; marital status; smoking; body mass index; estimated glomerular filtration rate; statin use; and history of diabetes, hypertension, cardiovascular disease, cancer, and emphysema. Model 2 included average daily step counts in addition to the covariates in model 1."}}},"facts":{"ages":{"id":"ages","kind":"statement","label":"Mean age of the three groups (0, 1-2, 3-7 days)","quote":"Age, mean (SD), y\n\n63.7 (19.3)\n\n51.5 (19.0)\n\n46.0 (15.5)"},"ard_1_2":{"id":"ard_1_2","kind":"estimate","label":"Fully adjusted risk difference, 1-2 days vs 0 days, all-cause","quote":"all-cause mortality risk was lower among those who took 8000 steps or more 1 to 2 days per week (aRD, −14.9%; 95% CI −18.8% to −10.9%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-14.9,"ciLow":-18.8,"ciHigh":-10.9,"unit":"points","absolute":true,"tier":"low"}},"ard_1_2_65plus":{"id":"ard_1_2_65plus","kind":"estimate","label":"Adjusted risk difference, 1-2 days, adults 65 and over","quote":"aged ≥65 years: aRD, −19.9% [95% CI, −30.8% to −8.9%]","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-19.9,"ciLow":-30.8,"ciHigh":-8.9,"unit":"points","absolute":true,"tier":"low"}},"ard_1_2_under65":{"id":"ard_1_2_under65","kind":"estimate","label":"Adjusted risk difference, 1-2 days, adults under 65","quote":"aged <65 years: aRD, −7.4% [95% CI, −11.2% to −3.7%]","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-7.4,"ciLow":-11.2,"ciHigh":-3.7,"unit":"points","absolute":true,"tier":"low"}},"ard_3_7":{"id":"ard_3_7","kind":"estimate","label":"Fully adjusted risk difference, 3-7 days vs 0 days, all-cause","quote":"3 to 7 days per week (aRD, −16.5%; 95% CI, −20.4% to −12.5%)","estimate":{"outcome":"10-year risk of death from any cause","measure":"aRD","point":-16.5,"ciLow":-20.4,"ciHigh":-12.5,"unit":"points","absolute":true,"tier":"low"}},"cohort":{"id":"cohort","kind":"context","label":"Who was enrolled, when, and how steps were measured","quote":"This cohort study evaluated a representative sample of participants aged 20 years or older in the National Health and Nutrition Examination Surveys 2005-2006 who wore an accelerometer for 1 week and their mortality data through December 31, 2019."},"confounding":{"id":"confounding","kind":"limitation","label":"Residual confounding by health status","quote":"our findings still have residual confounding bias (ie, poor health could influence daily step counts and mortality risk)"},"crude_0":{"id":"crude_0","kind":"estimate","label":"Share of the 0-day group who died within 10 years, unadjusted","quote":"257/632 (40.7)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":40.7,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"crude_1_2":{"id":"crude_1_2","kind":"estimate","label":"Share of the 1-2-day group who died within 10 years, unadjusted","quote":"75/532 (14.1)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":14.1,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"crude_3_7":{"id":"crude_3_7","kind":"estimate","label":"Share of the 3-7-day group who died within 10 years, unadjusted","quote":"107/1937 (5.5)","estimate":{"outcome":"Deaths from any cause within 10 years, unadjusted","measure":"proportion","point":5.5,"ciLow":null,"ciHigh":null,"unit":"%","absolute":true,"tier":"low"}},"followup":{"id":"followup","kind":"context","label":"Length of follow-up and number of deaths","quote":"Over the 10-year follow-up, all-cause and cardiovascular deaths occurred in 439 (14.2%) and 148 (5.3%) participants, respectively."},"hawthorne":{"id":"hawthorne","kind":"limitation","label":"People may walk more because they are wearing a tracker","quote":"as a result of knowledge that they are wearing the device, participants might have a tendency to be more active, a phenomenon known as the Hawthorne effect"},"mobility":{"id":"mobility","kind":"statement","label":"Number (%) with a mobility limitation in the three groups","quote":"Mobility limitation\n\n319 (50.5)\n\n108 (20.3)\n\n132 (6.8)"},"mobility_def":{"id":"mobility_def","kind":"context","label":"How mobility limitation was defined","quote":"Mobility limitations were defined as self-report of difficulty walking 0.25 miles without special equipment or climbing 10 stairs."},"models":{"id":"models","kind":"context","label":"What each adjustment model added","quote":"Model 1 included age; sex; race and ethnicity; insurance status; marital status; smoking; body mass index; estimated glomerular filtration rate; statin use; and history of diabetes, hypertension, cardiovascular disease, cancer, and emphysema. Model 2 included average daily step counts in addition to the covariates in model 1."},"one_week":{"id":"one_week","kind":"limitation","label":"Steps measured for a single week","quote":"because daily steps were only measured for 1 week at baseline, we did not have information on how changes in physical activity contribute to risk of mortality"},"parallel_meta":{"id":"parallel_meta","kind":"context","label":"Earlier meta-analysis on steps per day and mortality, cited by the authors","quote":"a recent meta-analysis showed decreasing mortality risks with an increasing number of daily steps until 6000 to 8000 steps are reached for adults older than 60 years and at 8000 to 10 000 steps per day for those younger than 60 years"},"plateau":{"id":"plateau","kind":"statement","label":"Where the curve flattened","quote":"the risk of mortality at 10 years rapidly decreased as the number of days per week taking 8000 steps or more increased and plateaued at 3 to 4 days"},"sample":{"id":"sample","kind":"context","label":"Number of participants","quote":"Among 3101 participants (mean [SD] age, 50.5 [18.4] years"},"threshold":{"id":"threshold","kind":"context","label":"How participants were grouped","quote":"Participants were grouped by the number of days per week they took 8000 steps or more (0 days, 1-2 days, and 3-7 days)."},"thresholds":{"id":"thresholds","kind":"statement","label":"Other step thresholds gave similar results","quote":"Different thresholds for the number of daily steps between 6000 and 10 000 yielded similar results."}}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('58929ab5-72ec-5a41-941b-be5f29965932', 'key_takeaways', '{"takeaways":[[{"text":"If a daily target keeps failing, the study''s lowest active group is a reasonable place to start: 8,000 steps on 1 to 2 days a week.","refs":["threshold","ard_1_2"]}],[{"text":"Past 3 to 4 such days the association flattened, so a missed day is no reason to write off the week.","refs":["plateau"]}],[{"text":"The association was widest in adults aged 65 and over, at 19.9 points against 7.4 points in younger adults.","refs":["ard_1_2_65plus","ard_1_2_under65"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('cd120d77-53a2-59fd-8bef-41a28b033ee7', '58929ab5-72ec-5a41-941b-be5f29965932', 1, 'Reached 8,000 steps today', 'Tick on any day your tracker shows 8,000 or more. A log, not a daily requirement.', 'action', 'none', null, null, null, null, null, null, null),
  ('fe0a3b64-2766-50aa-848f-6730306c5c7c', '58929ab5-72ec-5a41-941b-be5f29965932', 2, '8,000 steps on at least 1 day this week', 'The study''s 1-to-2-day group.', 'weekly_target', 'low', '10-year risk of death from any cause −14.9 points (95% CI −18.8 to −10.9)', 1, 'cd120d77-53a2-59fd-8bef-41a28b033ee7', null, null, null, null),
  ('8ae27155-81be-5408-9d91-309329f4f1f0', '58929ab5-72ec-5a41-941b-be5f29965932', 3, '8,000 steps on at least 3 days this week', 'The study''s 3-to-7-day group, where the association went flat.', 'weekly_target', 'low', '10-year risk of death from any cause −16.5 points (95% CI −20.4 to −12.5)', 3, 'cd120d77-53a2-59fd-8bef-41a28b033ee7', null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;

-- turmeric-pepper-breakfast
insert into public.papers (id, slug, title, doi, category, teaser, access_tier, published_at) values ('735a2dc7-8f80-59f4-afae-c49e591ae748', 'turmeric-pepper-breakfast', '1 g of black pepper in breakfast: what blood glucose did over the next 3 hours', '10.1002/fsn3.3965', 'Nutrition', 'Twenty healthy adults ate the same egg-and-toast breakfast four ways. With 1 g of black pepper in the egg, blood glucose was lower 30 minutes later. Added up over 3 hours, the meals did not differ.', 'free', '2026-11-13T13:46:30.346Z')
  on conflict (id) do update set slug = excluded.slug, title = excluded.title, doi = excluded.doi, category = excluded.category,
    teaser = excluded.teaser, access_tier = excluded.access_tier, published_at = coalesce(public.papers.published_at, excluded.published_at);
insert into public.paper_content (paper_id, content_json) values ('735a2dc7-8f80-59f4-afae-c49e591ae748', '{"hook":[{"text":"1 g of black pepper in a breakfast egg, and blood glucose was lower 30 minutes later.","refs":["in_egg","glucose_lower","glucose_30"]},{"text":"Added up over the full 3 hours, there was no difference.","refs":["glucose_total","nothing_else"]}],"populationPanel":[{"text":"Who this was tested in: 20 healthy adults, 10 men and 10 women.","refs":["sample"]},{"text":"The women averaged 21.4 years old and the men 21.9.","refs":["ages"]},{"text":"The entry rules asked for a body mass index of 18.5 to 24.9 and no chronic disease.","refs":["criteria"]},{"text":"Each person ate all four breakfasts in randomized order, a week apart.","refs":["crossover","washout"]},{"text":"The result describes one meal in people like these.","refs":["single_meal","sample"]},{"text":"It says nothing about diabetes or any other disease.","refs":["criteria"]}],"sections":[],"limitations":[],"layers":{"mechanism":{"paragraphs":[[{"text":"Think of a doorbell in your mouth.","refs":[]},{"text":"Food presses it, and the rest of the body hears that a meal is on the way.","refs":[]},{"text":"The authors point to a real one: a sensor in the mouth called TRPV1.","refs":["trpv1_mouth"]},{"text":"Black pepper carries a compound called piperine and several close relatives.","refs":["piperine","trpv1"]},{"text":"The authors say these might press that sensor.","refs":["trpv1"]}],[{"text":"What happens next is a hormone.","refs":[]},{"text":"When TRPV1 fires, levels of a gut hormone called GLP-1 go up in the lower gut and in the blood.","refs":["glp1"]},{"text":"GLP-1 is the gut''s message that food has arrived.","refs":["glp1","concept:glucagon-like-peptide"]},{"text":"It helps hold down the rise in blood sugar after eating, slows the gut and curbs appetite.","refs":["concept:glucagon-like-peptide"]}],[{"text":"That chain fits what the trial saw.","refs":[]},{"text":"After the pepper breakfast, blood glucose was lower than after the plain one.","refs":["glucose_lower"]},{"text":"The gap showed at the 30-minute reading.","refs":["glucose_30"]},{"text":"Hunger was lower too.","refs":["appetite"]}],[{"text":"Turmeric did not follow the script.","refs":[]},{"text":"On its own, 1 g did nothing to blood glucose.","refs":["turmeric_none"]},{"text":"The authors'' explanation is the dose: they call it low.","refs":["turmeric_dose"]}]],"figure":{"figure":"doorbell","caption":[{"text":"The authors'' explanation, step by step.","refs":["trpv1","glp1"]},{"text":"A dashed arrow is a step the trial did not measure.","refs":["lim_hormones"]}],"alt":"Four boxes, top to bottom, joined by dashed arrows. Pepper touches the mouth. A sensor there fires. The gut sends its food-has-arrived message. Blood sugar rises less. Only the last box is filled.","params":{"nodes":[{"lines":["Pepper touches the mouth"],"kind":"proposed","fact":{"id":"trpv1","kind":"statement","label":"Authors'' proposed mechanism: pepper compounds might act on the TRPV1 receptor","quote":"It was found that these effects are owing to the bio‐active profile of black pepper, such as isopiperine, isochavicine, piperine, piperanine, piperolein A and B, which might act on receptor TRPV1"}},{"lines":["A sensor there fires"],"kind":"proposed","fact":{"id":"trpv1_mouth","kind":"statement","label":"TRPV1 is in the mouth; the authors say its activation is known to affect glucose control and appetite","quote":"TRPV1 is present in the oral cavity and its activation is widely known to improve glucose homeostasis, potentially affect appetite responses as well as increase energy metabolism."}},{"lines":["The gut sends its","“food has arrived” message"],"kind":"proposed","fact":{"id":"glp1","kind":"statement","label":"TRPV1 activation raises GLP-1 in the lower small intestine and the blood (earlier work the authors cite)","quote":"Furthermore, TRPV1 activation increases GLP‐1; glucagon‐like peptide‐1 levels in the ileum and plasma."}},{"lines":["Blood sugar rises less"],"kind":"measured","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal (p < .05); direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}}}],"links":[{"kind":"proposed","fact":{"id":"trpv1","kind":"statement","label":"Authors'' proposed mechanism: pepper compounds might act on the TRPV1 receptor","quote":"It was found that these effects are owing to the bio‐active profile of black pepper, such as isopiperine, isochavicine, piperine, piperanine, piperolein A and B, which might act on receptor TRPV1"}},{"kind":"proposed","fact":{"id":"glp1","kind":"statement","label":"TRPV1 activation raises GLP-1 in the lower small intestine and the blood (earlier work the authors cite)","quote":"Furthermore, TRPV1 activation increases GLP‐1; glucagon‐like peptide‐1 levels in the ileum and plasma."}},{"kind":"proposed","fact":{"id":"trpv1_mouth","kind":"statement","label":"TRPV1 is in the mouth; the authors say its activation is known to affect glucose control and appetite","quote":"TRPV1 is present in the oral cavity and its activation is widely known to improve glucose homeostasis, potentially affect appetite responses as well as increase energy metabolism."}}]}}},"protocol":{"paragraphs":[[{"text":"The trial tested one dose: 1 g of black pepper, mixed into a fried egg.","refs":["in_egg"]},{"text":"The egg came with 2 slices of toast and a cup of sweet milk tea.","refs":["plate"]},{"text":"The participants ate after an overnight fast and finished within 10 minutes.","refs":["fast","eaten_in"]}],[{"text":"A second version added 1 g of turmeric to the pepper.","refs":["meals"]},{"text":"It showed the same early glucose difference, and tasters liked it more than pepper alone.","refs":["glucose_30","taste_rank"]},{"text":"Turmeric without pepper showed no glucose effect.","refs":["turmeric_none"]}],[{"text":"Each version was eaten once.","refs":["single_meal","washout"]},{"text":"The trial did not test a daily habit.","refs":["lim_long_term"]}]],"figure":{"figure":"five-readings","caption":[{"text":"Each dot is one reading.","refs":["timepoints"]},{"text":"Orange marks the readings that differed from the plain meal.","refs":["glucose_30"]}],"alt":"Four rows of five dots, one row for each meal. The readings were at 0, 30, 60, 120 and 180 minutes. At 30 minutes, the pepper meal and the both-spices meal are marked as differing from the plain meal. A bracket over all five readings says the total showed no difference.","params":{"times":[{"n":0,"ref":"timepoints"},{"n":30,"ref":"timepoints"},{"n":60,"ref":"timepoints"},{"n":120,"ref":"timepoints"},{"n":180,"ref":"timepoints"}],"unit":"min","meals":[{"label":"Plain","differed":[],"reading":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"}},{"label":"Pepper","differed":[{"n":30,"ref":"glucose_30"}],"reading":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"}},{"label":"Turmeric","differed":[],"reading":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no effect on blood glucose compared with the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}}},{"label":"Both spices","differed":[{"n":30,"ref":"glucose_30"}],"reading":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"}}],"pValue":{"text":".023","ref":"glucose_30"},"early":{"kind":"measured","fact":{"id":"glucose_30","kind":"finding","label":"differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal (p = .023); the text gives no size for the difference","quote":"So test meals (BP and BP + TR) show a significant effect for blood glucose level at the time point 30 min as compared to reference meal (C) (p = .023).","finding":{"outcome":"Blood glucose 30 minutes after the meal","tier":"low"}},"at":{"n":30,"ref":"glucose_30"}},"total":{"kind":"measured","fact":{"id":"glucose_total","kind":"finding","label":"no significant difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}}}}},"audit":{"effect":[{"text":"The paper''s text gives no size for the glucose difference.","refs":["glucose_30"]},{"text":"It says only that the two pepper meals differed from the plain meal at 30 minutes, with p = .023.","refs":["glucose_30"]}],"weakEnd":[{"text":"The paper reports no confidence interval for any glucose result.","refs":["glucose_30"]},{"text":"The gap could be wide or barely there; the text cannot say.","refs":["glucose_30"]},{"text":"Over the full 3 hours, total blood glucose did not differ between the four meals.","refs":["glucose_total","nothing_else"]}],"limitations":[[{"text":"The trial measured no hormones.","refs":["lim_hormones"]},{"text":"The sensor-and-hormone story is the authors'' idea, not a result.","refs":["lim_hormones","lim_mechanism"]}],[{"text":"Hunger and fullness were self-reported on paper scales.","refs":["appetite_scale"]},{"text":"The authors say the lower hunger might come from the spiced meals tasting worse.","refs":["lim_taste"]}],[{"text":"One breakfast per version, in 20 young adults: nothing here speaks to long-term use.","refs":["single_meal","sample","ages","lim_long_term"]}]],"missed":[{"text":"The easy summary: these spices are good for blood sugar.","refs":[]},{"text":"The paper found no glucose effect for turmeric alone.","refs":["turmeric_none"]},{"text":"The 3-hour total did not differ for any meal.","refs":["glucose_total","nothing_else"]},{"text":"Only healthy people took part, so the trial cannot speak to diabetes.","refs":["criteria","sample"]}],"more":[[{"text":"The paper does not say whether the participants knew which meal they had.","refs":[]}],[{"text":"The ingredient table lists 10 g of sugar for the combined meal and 8 g for the others.","refs":["sugar_row"]},{"text":"It still gives all four the same 50 g of carbohydrate.","refs":["carb_row"]}],[{"text":"Overall taste scores out of 9: plain 6.5, pepper 6.2, turmeric 6.1, both spices 6.6.","refs":["taste_scale","taste_c","taste_bp","taste_tr","taste_both"]}],[{"text":"Stomach and gut symptoms, also self-rated, did not differ between meals.","refs":["gut","gut_scale"]}],[{"text":"The authors name one weakness: they never measured the meals'' glycemic index.","refs":["lim_stated"]}]],"figure":null}},"glossary":[{"term":"randomized","plain":"Chance decided the order of the meals, not the people running the trial.","refs":["crossover"],"concept":null},{"term":"TRPV1","plain":"A sensor found in the mouth.","refs":["trpv1_mouth"],"concept":null},{"term":"GLP-1","plain":"A hormone the gut releases after a meal. It helps hold down the rise in blood sugar after eating, slows the gut and curbs appetite.","refs":[],"concept":"glucagon-like-peptide"},{"term":"piperine","plain":"The main active ingredient of black pepper.","refs":["piperine"],"concept":null},{"term":"blood glucose","plain":"The sugar carried in the blood, measured here from a finger prick.","refs":["finger_prick"],"concept":null}],"primaryEstimate":"glucose_30","simulator":{"kind":"breakfast-meals","params":{"participants":{"n":20,"ref":"sample"},"earlyMinutes":{"n":30,"ref":"glucose_30"},"totalMinutes":{"n":180,"ref":"timepoints"},"tasteMax":{"n":9,"ref":"taste_scale"},"meals":[{"id":"plain","label":"Plain egg and toast","added":"Nothing added. Every other meal is compared with this one.","glucoseEarly":{"result":"reference","fact":null},"glucoseTotal":{"result":"reference","fact":null},"hunger":{"result":"reference","fact":null},"gut":{"result":"reference","fact":null},"taste":{"n":6.5,"ref":"taste_c"}},{"id":"pepper","label":"With black pepper","added":"Black pepper in the egg, at the dose the trial tested.","glucoseEarly":{"result":"lower","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal (p < .05); direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}}},"glucoseTotal":{"result":"same","fact":{"id":"glucose_total","kind":"finding","label":"no significant difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"hunger":{"result":"lower","fact":{"id":"appetite","kind":"finding","label":"less hunger and less perceived eating ability, more satiety, after the pepper meal and the pepper-plus-turmeric meal; no sizes given","quote":"A decrease in perceived eating ability and hunger, and an increase in satiety after BP + TR and BP meal was observed.","finding":{"outcome":"Self-rated hunger, satiety and how much they felt they could eat","tier":"low"}}},"gut":{"result":"same","fact":{"id":"gut","kind":"finding","label":"no significant difference between meals or over time (p > .05)","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}}},"taste":{"n":6.2,"ref":"taste_bp"}},{"id":"turmeric","label":"With turmeric","added":"Turmeric in the egg, at the dose the trial tested.","glucoseEarly":{"result":"same","fact":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no effect on blood glucose compared with the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}}},"glucoseTotal":{"result":"same","fact":{"id":"glucose_total","kind":"finding","label":"no significant difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"hunger":{"result":"none_reported","fact":null},"gut":{"result":"same","fact":{"id":"gut","kind":"finding","label":"no significant difference between meals or over time (p > .05)","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}}},"taste":{"n":6.1,"ref":"taste_tr"}},{"id":"both","label":"With both spices","added":"Black pepper and turmeric together in the egg.","glucoseEarly":{"result":"lower","fact":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal (p < .05); direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}}},"glucoseTotal":{"result":"same","fact":{"id":"glucose_total","kind":"finding","label":"no significant difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}}},"hunger":{"result":"lower","fact":{"id":"appetite","kind":"finding","label":"less hunger and less perceived eating ability, more satiety, after the pepper meal and the pepper-plus-turmeric meal; no sizes given","quote":"A decrease in perceived eating ability and hunger, and an increase in satiety after BP + TR and BP meal was observed.","finding":{"outcome":"Self-rated hunger, satiety and how much they felt they could eat","tier":"low"}}},"gut":{"result":"same","fact":{"id":"gut","kind":"finding","label":"no significant difference between meals or over time (p > .05)","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}}},"taste":{"n":6.6,"ref":"taste_both"}}]}},"facts":{"ages":{"id":"ages","kind":"context","label":"Average age, body mass index and fasting blood glucose of the people who actually took part","quote":"The mean age of female students was 21.4 ± 0.72 years with a mean BMI of 23.5 ± 3.9 and fasting blood glucose of 73.5 ± 9.05 mg/dL. For boys the mean age was 21.9 ± 0.84, BMI was 23.22 ± 5.7, and fasting blood glucose was 77.35 ± 9.57 mg/dL."},"appetite":{"id":"appetite","kind":"finding","label":"less hunger and less perceived eating ability, more satiety, after the pepper meal and the pepper-plus-turmeric meal; no sizes given","quote":"A decrease in perceived eating ability and hunger, and an increase in satiety after BP + TR and BP meal was observed.","finding":{"outcome":"Self-rated hunger, satiety and how much they felt they could eat","tier":"low"}},"appetite_scale":{"id":"appetite_scale","kind":"context","label":"Appetite was rated by the participants on 100 mm lines","quote":"Appetite was assessed by using VAS (Flint et al., ). The VAS consisted of four scales, each of 100 mm length, which was used to determine the participant''s hunger from 0 to 100 mm"},"carb_row":{"id":"carb_row","kind":"context","label":"Table 1 gives all four meals the same carbohydrate total","quote":"Average CHO (g) | 50 | 50 | 50 | 50 |"},"criteria":{"id":"criteria","kind":"context","label":"Who could take part: age, body mass index, no chronic disease","quote":"Inclusion criteria were: free from chronic diseases, aged 18–60 years, and healthy individual with body mass index (BMI) (18.5–24.9 kg/m2) medically healthy."},"crossover":{"id":"crossover","kind":"context","label":"Design: randomized crossover, four test meals, each with 50 g of carbohydrate","quote":"The study made use of a randomized crossover design; all the subjects were provided with 04 test foods, all have 50 g carbohydrate content."},"eaten_in":{"id":"eaten_in","kind":"context","label":"Meal eaten within 10 minutes","quote":"Next, the test meals, supplying 50 g of accessible carbohydrates, were ingested in 10 min."},"fast":{"id":"fast","kind":"context","label":"Overnight fast before each visit","quote":"Selected personnel were instructed to take their twilight meal up to 10:00 p.m. following which they were asked to fast"},"finger_prick":{"id":"finger_prick","kind":"context","label":"Blood glucose measured with a glucometer from a finger prick","quote":"was employed to compute the blood glucose, and samples were collected via finger prick"},"glp1":{"id":"glp1","kind":"statement","label":"TRPV1 activation raises GLP-1 in the lower small intestine and the blood (earlier work the authors cite)","quote":"Furthermore, TRPV1 activation increases GLP‐1; glucagon‐like peptide‐1 levels in the ileum and plasma."},"glucose_30":{"id":"glucose_30","kind":"finding","label":"differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal (p = .023); the text gives no size for the difference","quote":"So test meals (BP and BP + TR) show a significant effect for blood glucose level at the time point 30 min as compared to reference meal (C) (p = .023).","finding":{"outcome":"Blood glucose 30 minutes after the meal","tier":"low"}},"glucose_lower":{"id":"glucose_lower","kind":"finding","label":"lower than the control meal after the pepper meal and the pepper-plus-turmeric meal (p < .05); direction stated in the abstract, no size given","quote":"Experimental meals BP and BP + TR resulted in lower blood glycemia (p < .05) significantly compared to control meal.","finding":{"outcome":"Blood glucose after the meal","tier":"low"}},"glucose_total":{"id":"glucose_total","kind":"finding","label":"no significant difference between the four meals over the whole 3 hours","quote":"Incremental area under the curves (iAUCs) among the test meals shows a non‐significant effect.","finding":{"outcome":"Total rise in blood glucose over 3 hours (incremental area under the curve)","tier":"low"}},"gut":{"id":"gut","kind":"finding","label":"no significant difference between meals or over time (p > .05)","quote":"There was no significant (p > .05) effect of time, treatment, and time × treatment on postprandial responses of gastrointestinal symptoms.","finding":{"outcome":"Self-rated stomach and gut symptoms","tier":"low"}},"gut_scale":{"id":"gut_scale","kind":"context","label":"Gut symptoms were rated by the participants on a 4-point scale","quote":"Gastrointestinal symptoms such as swelling of stomach, uneasy feelings, flatulence, loose stools, diarrhea, constipation, cramping, and grumbling were assessed using a 4‐point Likert scale."},"in_egg":{"id":"in_egg","kind":"context","label":"How the spice was given: powder mixed into the fried egg","quote":"In test meals black pepper (1 g) and turmeric powder (1 g) were added to the egg."},"lim_hormones":{"id":"lim_hormones","kind":"limitation","label":"The proposed mechanism was not measured: no hormones were examined","quote":"However, hormones involved in the regulation of satiety were not examined in this intervention."},"lim_long_term":{"id":"lim_long_term","kind":"limitation","label":"No long-term data: the authors call for long-term studies","quote":"Future long‐term studies with increased dosage of turmeric and black pepper are considered necessary to understand the advantages of long‐term utilization of turmeric and black pepper supplemented breakfast"},"lim_mechanism":{"id":"lim_mechanism","kind":"limitation","label":"The authors say the mechanisms still need investigating","quote":"The potential components of turmeric and black pepper and actual physiological mechanisms involved in these effects need further investigation."},"lim_stated":{"id":"lim_stated","kind":"limitation","label":"The authors'' own stated limitation: the glycemic index of the meals was not measured","quote":"This study has some deficiencies. The glycemic index of the test meals was not noted and it necessitates the need to be explored in future research studies."},"lim_taste":{"id":"lim_taste","kind":"limitation","label":"The drop in hunger may be a taste effect: the spiced meals were liked less","quote":"The reported reduction in hunger after BP and BP + TR meal consumption might be because of decreased palatability since different scientific approaches have revealed an enormous effect of palatability on appetite"},"meals":{"id":"meals","kind":"context","label":"The four test meals and the spice doses","quote":"Test foods were: (1) bread toast and egg (control diet), (2) bread toast and egg +1 g black pepper (BP), (3) bread toast and egg +1 g turmeric (TR), and (4) bread toast and egg +1 g black pepper +1 g turmeric (BP + TR), all meals were served with tea."},"nothing_else":{"id":"nothing_else","kind":"context","label":"No other food or drink for the 3 hours","quote":"The ingestion of any kind of food or beverage during the period of 3 h was precluded"},"piperine":{"id":"piperine","kind":"context","label":"Black pepper''s main active ingredient is piperine","quote":"Black pepper (Piper nigrum) family piperaceae, with the main active ingredient piperine, has a hypoglycaemic effect (Panda & Kar, )."},"plate":{"id":"plate","kind":"context","label":"What else was on the plate: two toasts and a cup of sweet milk tea","quote":"The fried egg was served with 2 standard bread toasts and a cup of black tea (250 mL) having 200 mL milk, 50 mL water, 1 teaspoon black tea (5 g), and 1 tablespoon sugar (8 g)."},"sample":{"id":"sample","kind":"context","label":"Number and sex of participants","quote":"For this study, a total of 20 healthy individuals comprising 10 males and 10 females, were enrolled through direct personal communication."},"single_meal":{"id":"single_meal","kind":"context","label":"The authors call this an acute intervention (one meal per condition)","quote":"The decrease in hunger and perceived eating ability and increase in satiety and fullness after BP + TR and BP meal in this acute intervention"},"sugar_row":{"id":"sugar_row","kind":"context","label":"Table 1 lists 10 g of sugar for the combined meal and 8 g for the other three","quote":"Sugar (g) | 08 | 08 | 08 | 10 |"},"taste_both":{"id":"taste_both","kind":"statement","label":"Table 3, pepper-plus-turmeric meal. Overall pleasantness: 6.6","quote":"BP + TR | 6.5 ± 0.49b\n| 6.2 ± 0.52b\n| 6.2 ± 0.46b\n| 6.5 ± 0.44b\n| 6.6 ± 0.42b"},"taste_bp":{"id":"taste_bp","kind":"statement","label":"Table 3, black pepper meal. Overall pleasantness: 6.2","quote":"BP | 5.9 ± 0.55a\n| 5.35 ± 0.61a\n| 6.05 ± 0.58ab\n| 5.9 ± 0.55a\n| 6.2 ± 0.50a"},"taste_c":{"id":"taste_c","kind":"statement","label":"Table 3, control meal: appearance, texture, smell, taste, overall pleasantness (mean ± SD, 9-point scale). Overall: 6.5","quote":"C | 6.3 ± 0.48b\n| 6.4 ± 0.46b\n| 5.5 ± 0.51a\n| 6.7 ± 0.48b\n| 6.5 ± 0.39ab"},"taste_rank":{"id":"taste_rank","kind":"finding","label":"the control meal and the combined meal were rated higher than the pepper-only and turmeric-only meals (p < .05)","quote":"Post hoc pair‐wise comparison shows that the control meal and combined meal have significantly (p < .05) higher acceptability than (BP and TR) meal in comparison of general appearance, consistency, smell, taste, and whole pleasantness.","finding":{"outcome":"Palatability (appearance, texture, smell, taste, overall pleasantness)","tier":"low"}},"taste_scale":{"id":"taste_scale","kind":"context","label":"Taste was rated on a 9-point scale from dislike extremely to like extremely","quote":"A 9‐point hedonic calibration was exploited with dislike extremely on one end and like extremely on the other end."},"taste_tr":{"id":"taste_tr","kind":"statement","label":"Table 3, turmeric meal. Overall pleasantness: 6.1","quote":"TR | 5.7 ± 0.48a\n| 5.5 ± 0.47a\n| 5.6 ± 0.533a\n| 5.9 ± 0.47a\n| 6.1 ± 0.40a"},"timepoints":{"id":"timepoints","kind":"context","label":"When blood glucose was measured","quote":"blood glucose levels were recorded at 0, 30, 60, 120, and 180 min"},"trpv1":{"id":"trpv1","kind":"statement","label":"Authors'' proposed mechanism: pepper compounds might act on the TRPV1 receptor","quote":"It was found that these effects are owing to the bio‐active profile of black pepper, such as isopiperine, isochavicine, piperine, piperanine, piperolein A and B, which might act on receptor TRPV1"},"trpv1_mouth":{"id":"trpv1_mouth","kind":"statement","label":"TRPV1 is in the mouth; the authors say its activation is known to affect glucose control and appetite","quote":"TRPV1 is present in the oral cavity and its activation is widely known to improve glucose homeostasis, potentially affect appetite responses as well as increase energy metabolism."},"turmeric_dose":{"id":"turmeric_dose","kind":"statement","label":"Authors'' guess at why turmeric alone did nothing: the dose was low","quote":"A possible rationale for this may be the use of low dose of turmeric powder in this study."},"turmeric_none":{"id":"turmeric_none","kind":"finding","label":"turmeric alone: no effect on blood glucose compared with the control meal","quote":"Contradictory to the assumption of this current approach, no remarkable effect of TR (1 g) meal on postprandial blood sugar level was noticed.","finding":{"outcome":"Blood glucose after the turmeric-only meal","tier":"low"}},"washout":{"id":"washout","kind":"context","label":"Each person ate all four meals, one per visit, a week apart","quote":"Every subject attended four sessions with 1 week washout period between the trials."}},"context":{"studies":[],"concepts":[{"slug":"glucagon-like-peptide","term":"glucagon-like peptide","plain":"A hormone the gut releases after a meal. It helps hold down the rise in blood sugar after eating, slows the gut and curbs appetite.","model":"The gut''s message that food has arrived: deal with the sugar, slow the conveyor, stop asking for more.","reference":{"doi":"10.1152/physrev.00034.2006","title":"The physiology of glucagon-like peptide 1"}}]}}'::jsonb)
  on conflict (paper_id) do update set content_json = excluded.content_json, updated_at = now();
insert into public.paper_feature_content (paper_id, feature_key, payload) values ('735a2dc7-8f80-59f4-afae-c49e591ae748', 'key_takeaways', '{"takeaways":[[{"text":"The dose tested was 1 g of black pepper, cooked into the egg of a toast-and-tea breakfast.","refs":["in_egg","plate"]}],[{"text":"The glucose difference showed 30 minutes after eating and not in the 3-hour total.","refs":["glucose_30","glucose_total","nothing_else"]}],[{"text":"Turmeric alone, at 1 g, showed no glucose effect.","refs":["turmeric_none"]}]]}'::jsonb)
  on conflict (paper_id, feature_key) do update set payload = excluded.payload, updated_at = now();
insert into public.protocol_steps (id, paper_id, position, label, detail, kind, evidence_grade, source_estimate, target_per_week, counts_step_id, condition_key, condition_value, applies_when, retired_at) values
  ('153827fc-001f-5428-ab08-1d5e6da2d9cc', '735a2dc7-8f80-59f4-afae-c49e591ae748', 1, '1 g of black pepper in my breakfast', 'The dose this trial tested, cooked into an egg. It did not test more, less or other meals.', 'action', 'low', 'Blood glucose 30 minutes after the meal: differed from the control meal 30 minutes after eating, for the pepper meal and the pepper-plus-turmeric meal (p = .023); the text gives no size for the difference', null, null, null, null, null, null),
  ('72924d31-4867-5fbd-a568-8b5059af38f4', '735a2dc7-8f80-59f4-afae-c49e591ae748', 2, '1 g of turmeric with the pepper', 'Tested together with pepper. Turmeric alone showed no glucose effect, so this carries no weight.', 'action', 'none', null, null, null, null, null, null, null)
  on conflict (id) do update set position = excluded.position, label = excluded.label, detail = excluded.detail, kind = excluded.kind,
    -- A withdrawn paper keeps weight 0 no matter what the content files say.
    evidence_grade = case when (select withdrawn_at from public.papers where id = excluded.paper_id) is null then excluded.evidence_grade else 'none' end,
    source_estimate = excluded.source_estimate, target_per_week = excluded.target_per_week, counts_step_id = excluded.counts_step_id,
    condition_key = excluded.condition_key, condition_value = excluded.condition_value, applies_when = excluded.applies_when,
    retired_at = case when excluded.retired_at is null then null else coalesce(public.protocol_steps.retired_at, excluded.retired_at) end;
